  values
    ((select id from s), 1, 'Count your blessings before your burdens', 'Forgetfulness is a quiet danger for believers — we replay our problems more than the provisions God has already given. The wilderness generation saw miracles and still forgot how great their God was.', array['Psalm 103:2','Deuteronomy 8:11']),
    ((select id from s), 2, 'Everything we have comes from God', 'Gratitude recognises the source. Whatever we possess, achieve or are able to do is by God''s grace. Pride forgets the source — as Nebuchadnezzar boasted ''is this not the great Babylon I built'' and was brought down.', array['James 1:17','1 Corinthians 4:7']),
    ((select id from s), 3, 'Gratitude must continue in the hard seasons', 'Gratitude in abundance is easy; gratitude in difficulty is more powerful because it shows faith when circumstances aren''t good. Habakkuk praises though everything fails; Job blesses God after losing everything. Don''t let a temporary problem erase your permanent blessings.', array['Habakkuk 3:17','Job 1:21','Romans 8:28']),
    ((select id from s), 4, 'Gratitude opens doors for greater blessing', 'Ten lepers were healed; one came back to say thank you and was made whole. Are we the one, or one of the nine? Thankfulness attracts God''s attention; complaining magnifies the problem.', array['Luke 17:11-19','Philippians 4:6']),
    ((select id from s), 5, 'The greatest reason is our salvation', 'Among all blessings, salvation is the greatest because it is eternal, not temporary. While we were still sinners Christ died for us — we did nothing to deserve it; it is grace.', array['Romans 5:8','Ephesians 2:8'])
  returning 1
)
